text:
{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall sharing equally",
      "look_at": {
        "kind": "picture",
        "shows": "Two plates with different numbers of strawberries"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the learning objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach halves and quarters of shapes",
      "look_at": {
        "kind": "diagram",
        "shows": "Matching rectangles with one of two or four equal parts shaded"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Correct the belief that any two parts are halves",
      "look_at": {
        "kind": "diagram",
        "shows": "A rectangle split into unequal parts beside one split equally"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Identify halves and quarters independently",
      "look_at": {
        "kind": "diagram",
        "shows": "Three shapes with different numbers of equal parts shaded"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Model finding half by sharing",
      "look_at": {
        "kind": "diagram",
        "shows": "Twelve counters shared into two equal groups"
      },
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Try a matching half problem",
      "look_at": {
        "kind": "diagram",
        "shows": "Fourteen counters ready to share"
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Model finding a quarter by sharing",
      "look_at": {
        "kind": "diagram",
        "shows": "Twelve counters shared into four equal groups"
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Try a matching quarter problem",
      "look_at": {
        "kind": "diagram",
        "shows": "Sixteen counters ready to share"
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Check the meaning of one quarter",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Practise sharing amounts independently",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2, 3]
    },
    {
      "slide": 12,
      "does": "Apply fractions to new situations",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Are these strawberries shared equally?",
    "picture": {
      "shows": "Two identical plates, one holding two strawberries and the other holding four",
      "must_see": [
        "two matching plates",
        "two strawberries",
        "four strawberries"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        {
          "label": "One half",
          "text": "One of two equal parts."
        },
        {
          "label": "One quarter",
          "text": "One of four equal parts."
        }
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two identical rectangles show one half and one quarter shaded",
        "alt": "One rectangle has one of two equal parts shaded. Another has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {
            "shape": "rectangle",
            "parts": 2,
            "cut": "vertical",
            "shaded": 1,
            "name": "half"
          },
          {
            "shape": "rectangle",
            "parts": 4,
            "cut": "vertical",
            "shaded": 1,
            "name": "quarter"
          }
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Two parts are not always halves",
      "lead": "Halves must be equal in size.",
      "points": [
        "A has two unequal parts: not halves.",
        "B has two equal parts: halves."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "Two identical rectangles side by side: A divided vertically into a narrow part and a part three times as wide; B divided vertically into two equal parts. Shade the left part of each.",
        "labels": ["A", "B"]
      }
    },
    {
      "template": "big-visual",
      "heading": "Find the fractions",
      "lead": "Which shows one half? Which shows one quarter?",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Three shapes for pupils to identify by their shaded parts",
        "alt": "A has one of two equal parts shaded. B has one of four shaded. C has three of four shaded.",
        "title": null,
        "shapes": [
          {
            "shape": "circle",
            "parts": 2,
            "cut": "auto",
            "shaded": 1,
            "name": "A"
          },
          {
            "shape": "square",
            "parts": 4,
            "cut": "grid",
            "shaded": 1,
            "name": "B"
          },
          {
            "shape": "rectangle",
            "parts": 4,
            "cut": "vertical",
            "shaded": 3,
            "name": "C"
          }
        ]
      }
    },
    {
      "template": "steps",
      "heading": "Find half of 12",
      "points": [
        "Start with 12 counters.",
        "Share into two equal groups.",
        "Count one group: half of 12 is 6."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared equally between two rings",
        "alt": "Two equal groups each contain six counters.",
        "title": null,
        "total": 12,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find half of 14",
      "lead": "Draw two equal groups. How many are in one group?",
      "figure": {
        "kind": "equal-groups",
        "shows": "Fourteen unshared counters in a single ring, ready for pupils to draw and share into two equal groups",
        "alt": "Fourteen counters are together in one ring.",
        "title": null,
        "total": 14,
        "groups": 10,
        "layout": "rings",
        "show_count": "none",
        "unknown": null
      }
    },
    {
      "template": "steps",
      "heading": "Find a quarter of 12",
      "points": [
        "Start with 12 counters.",
        "Share into four equal groups.",
        "Count one group: a quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared equally between four rings",
        "alt": "Four equal groups each contain three counters.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find a quarter of 16",
      "lead": "Draw four equal groups. How many are in one group?",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen unshared counters in a single ring, ready for pupils to draw and share into four equal groups",
        "alt": "Sixteen counters are together in one ring.",
        "title": null,
        "total": 16,
        "groups": 10,
        "layout": "rings",
        "show_count": "none",
        "unknown": null
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the answer",
      "stem": "What is one quarter of 8?",
      "options": [
        "2",
        "4",
        "8"
      ],
      "correct": 1
    },
    {
      "template": "practice",
      "heading": "Draw and share",
      "questions": [
        "Find half of 18.",
        "Find one quarter of 4.",
        "Find one quarter of 20."
      ],
      "instruction": "Draw equal groups. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Use what you know",
      "questions": [
        "Draw a square. Show one quarter shaded.",
        "Half of 20 apples are red. How many are red?",
        "Four children share 8 buns equally. What fraction does each get?"
      ],
      "instruction": "Draw or write your answers. Explain the last one.",
      "picture": null
    }
  ]
}
